115	func TestStorageStatsCounting(t *testing.T) {
116		h := Handler()
117	
118		// Empty object counts only toward objects.
119		upload(t, h, nil)
120		st := getStats(t, h)
121		if st.Objects != 1 || st.LogicalBytes != 0 || st.Blocks != 0 || st.StoredBytes != 0 {
122			t.Fatalf("stats after empty object = %+v", st)
123		}
124	
125		// One object whose body repeats the same chunk-sized prefix: the
126		// repeated block is stored and counted once.
127		chunk := bytes.Repeat([]byte("a"), ChunkSize)
128		body := append(append([]byte{}, chunk...), chunk...)
129		resp := upload(t, h, body)
130		if len(resp.Chunks) != 2 || resp.Chunks[0] != resp.Chunks[1] {
131			t.Fatalf("expected two identical chunks, got %v", resp.Chunks)
132		}
133		st = getStats(t, h)
134		want := statsResponse{Objects: 2, LogicalBytes: 2 * ChunkSize, Blocks: 1, StoredBytes: ChunkSize}
135		if st != want {
136			t.Fatalf("stats = %+v, want %+v", st, want)
137		}
138	
139		// A second object sharing the same block adds logical bytes only.
140		other := append(append([]byte{}, chunk...), []byte("tail")...)
141		resp2 := upload(t, h, other)
142		st = getStats(t, h)
143		want = statsResponse{
144			Objects:      3,
145			LogicalBytes: 2*ChunkSize + ChunkSize + 4,
146			Blocks:       2,
147			StoredBytes:  ChunkSize + 4,
148		}
149		if st != want {
150			t.Fatalf("stats = %+v, want %+v", st, want)
151		}
152	
153		// Re-uploading an existing object changes nothing.
154		upload(t, h, body)
155		upload(t, h, other)
156		if st = getStats(t, h); st != want {
157			t.Fatalf("stats after duplicate uploads = %+v, want %+v", st, want)
158		}
159	
160		// Both shared blocks stay readable.
161		for _, cid := range append(resp.Chunks[:1], resp2.Chunks[1]) {
162			if rec := getBlock(t, h, cid); rec.Code != http.StatusOK {
163				t.Fatalf("block %s: status = %d, want %d", cid, rec.Code, http.StatusOK)
164			}
165		}
166	}
