168	func TestStorageStatsAcrossGC(t *testing.T) {
169		h := Handler()
170		shared := bytes.Repeat([]byte("s"), ChunkSize)
171		pinned := upload(t, h, append(append([]byte{}, shared...), []byte("kept")...))
172		doomed := upload(t, h, append(append([]byte{}, shared...), []byte("gone")...))
173	
174		// Pin the first object so only the second is collected.
175		rec := putPin(t, h, pinned.CID, `{}`, "application/json")
176		if rec.Code != http.StatusCreated {
177			t.Fatalf("pin status = %d, want %d", rec.Code, http.StatusCreated)
178		}
179	
180		// Dry run changes neither objects, blocks, nor stats.
181		mustGC(t, h, "?dryRun=true")
182		before := statsResponse{Objects: 2, LogicalBytes: 2 * (ChunkSize + 4), Blocks: 3, StoredBytes: ChunkSize + 8}
183		if st := getStats(t, h); st != before {
184			t.Fatalf("stats after dry run = %+v, want %+v", st, before)
185		}
186		for _, cid := range doomed.Chunks {
187			if rec := getBlock(t, h, cid); rec.Code != http.StatusOK {
188				t.Fatalf("block %s after dry run: status = %d, want %d", cid, rec.Code, http.StatusOK)
189			}
190		}
191	
192		mustGC(t, h, "")
193		after := statsResponse{Objects: 1, LogicalBytes: ChunkSize + 4, Blocks: 2, StoredBytes: ChunkSize + 4}
194		if st := getStats(t, h); st != after {
195			t.Fatalf("stats after gc = %+v, want %+v", st, after)
196		}
197	
198		// The shared block remains readable; the exclusive block is gone.
199		if rec := getBlock(t, h, doomed.Chunks[0]); rec.Code != http.StatusOK {
200			t.Fatalf("shared block: status = %d, want %d", rec.Code, http.StatusOK)
201		}
202		rec = getBlock(t, h, doomed.Chunks[1])
203		if rec.Code != http.StatusNotFound {
204			t.Fatalf("unreferenced block: status = %d, want %d", rec.Code, http.StatusNotFound)
205		}
206		assertErrorCode(t, rec, "block_not_found")
207	}
