1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"net/http/httptest"
8		"sort"
9		"strings"
10		"sync"
11		"testing"
12		"time"
13	)
14	
15	// dirEntrySpec describes one directory entry while building test fixtures.
16	type dirEntrySpec struct {
17		name string
18		typ  string
19		cid  string
20	}
21	
22	// marshalDirectory encodes a canonical, contract-conformant directory
23	// document with entries sorted strictly by Unicode code point.
24	func marshalDirectory(t *testing.T, entries []dirEntrySpec) []byte {
25		t.Helper()
26		sorted := append([]dirEntrySpec(nil), entries...)
27		sort.Slice(sorted, func(i, j int) bool { return runesLess(sorted[i].name, sorted[j].name) })
28		seen := map[string]bool{}
29		type entryJSON struct {
30			Name string `json:"name"`
31			Type string `json:"type"`
32			CID  string `json:"cid"`
33		}
34		doc := struct {
35			Version int         `json:"version"`
36			Entries []entryJSON `json:"entries"`
37		}{Version: directoryVersion, Entries: []entryJSON{}}
38		for _, e := range sorted {
39			if seen[e.name] {
40				t.Fatalf("duplicate entry name %q while building fixture", e.name)
41			}
42			seen[e.name] = true
43			doc.Entries = append(doc.Entries, entryJSON{Name: e.name, Type: e.typ, CID: e.cid})
44		}
45		body, err := json.Marshal(doc)
46		if err != nil {
47			t.Fatal(err)
48		}
49		return body
50	}
51	
52	// upload stores arbitrary bytes through POST /v1/objects and returns the CID.
53	func uploadBytes(t *testing.T, h http.Handler, body []byte) string {
54		t.Helper()
55		rec := postBody(t, h, body, "application/octet-stream")
56		if rec.Code != http.StatusCreated && rec.Code != http.StatusOK {
57			t.Fatalf("upload status = %d: %s", rec.Code, rec.Body.String())
58		}
59		return decodeObjectResponse(t, rec).CID
60	}
61	
62	// gatewayRequest issues a gateway GET using the raw target verbatim, so
63	// percent escapes survive exactly as written.
64	func gatewayRequest(h http.Handler, target string) *httptest.ResponseRecorder {
65		rec := httptest.NewRecorder()
66		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, target, nil))
67		return rec
68	}
69	
70	// gatewayRequestRaw issues a gateway request whose request target would not
71	// survive net/url parsing (e.g. an invalid percent escape), setting
72	// RequestURI directly as a real server would hand it to the handler.
73	func gatewayRequestRaw(h http.Handler, method, target string) *httptest.ResponseRecorder {
74		rec := httptest.NewRecorder()
75		req := &http.Request{Method: method, RequestURI: target}
76		h.ServeHTTP(rec, req)
77		return rec
78	}
79	
80	// buildTree stores a file, a leaf directory referencing it, and a root
81	// directory referencing both. It returns the CIDs of root, subdir and file.
82	func buildTree(t *testing.T, h http.Handler) (rootCID, subCID, fileCID string) {
83		t.Helper()
84		fileCID = uploadBytes(t, h, []byte("file-bytes"))
85		subCID = uploadBytes(t, h, marshalDirectory(t, []dirEntrySpec{
86			{name: "inner.txt", typ: "file", cid: fileCID},
87		}))
88		rootCID = uploadBytes(t, h, marshalDirectory(t, []dirEntrySpec{
89			{name: "sub", typ: "directory", cid: subCID},
90			{name: "top.txt", typ: "file", cid: fileCID},
91		}))
92		return rootCID, subCID, fileCID
93	}
