97		rootCID, subCID, fileCID := buildTree(t, h)
98		rootBody := marshalDirectory(t, []dirEntrySpec{
99			{name: "sub", typ: "directory", cid: subCID},
100			{name: "top.txt", typ: "file", cid: fileCID},
101		})
102	
